                    "type": "vis",
                    "config": {
                      "type": "xy",
                      "title": "Requests over time (ES|QL)",
                      "layers": [
                        {
                          "type": "line",
                          "data_source": {
                            "type": "esql",
                            "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
                          },
                          "x": {
                            "column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
                          },
                "fields": [
                  "response.keyword"
                ],
                "limit": 5
              }
            ]
          }
      - label: Create a visualization using a library data view - cURL
        lang: cURL_library
        source: |
          curl -X POST "${KIBANA_URL}/api/visualizations" \
            -H "Authorization: ApiKey ${API_KEY}" \
            -H "kbn-xsrf: true" \
            -H "Content-Type: application/json" \
            -d '{
            "type": "metric",
            "title": "Total requests (library data view)",
            "data_source": {
              "type": "data_view_reference",
              "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"
            },
            "metrics": [
              {
                "type": "primary",
                "operation": "count"
              }
            ]
          }'
      - label: Create a visualization using a library data view - Console
        lang: Console_library
        source: |
          POST kbn:/api/visualizations
          {
            "type": "metric",
            "title": "Total requests (library data view)",
            "data_source": {
              "type": "data_view_reference",
              "ref_id": "90943e30-9a47-11e8-b64d-95841ca0b247"
            },
            "metrics": [
              {
                "type": "primary",
                "operation": "count"
              }
            ]
          }
    x-state: Generally available; added in 9.5.0
    x-metaTags:
      - content: Kibana
        name: product_name
/api/visualizations/{id}:
  delete:
    description: Permanently deletes a Lens visualization. If the visualization is referenced by a dashboard panel, the panel shows an error after deletion.
    operationId: delete-visualizations-id
    parameters:
      - description: A required header to protect against CSRF attacks
        in: header
        name: kbn-xsrf
        required: true
        schema:
          example: 'true'

